["rlt_text1202"]={["arg1"]=[[文本输出]],["arg2"]=[[你想顺着灶突进入，但开口太小了，你不但没有挤进去，反而沾了一身灰。]],["id"]=[[rlt_text1202]]},["rlt_text1203"]={["arg1"]=[[文本输出]],["arg2"]=[[你轻轻打开窗户，翻身进了里面。]],["id"]=[[rlt_text1203]],["jobstart"]=[[fb28rw06]]},["rlt_text1204"]={["arg1"]=[[文本输出]],["arg2"]=[[你将门闩打开，拉开了门，喜儿窜了进来。]],["id"]=[[rlt_text1204]]},["rlt_text13"]={["arg1"]=[[文本输出]],["arg2"]=[[你打开了石棺，但是什么都没有发现。]],["id"]=[[rlt_text13]]},["rlt_text1300"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻开衣柜，里面都是衣物，没什么可用的。]],["id"]=[[rlt_text1300]]},["rlt_text1301"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻开衣柜，找到一件样式奇特的衣物。]],["id"]=[[rlt_text1301]]},["rlt_text1302"]={["arg1"]=[[文本输出]],["arg2"]=[[在防具的保护下，你顺利地采到了蜂蜜。]],["id"]=[[rlt_text1302]]},["rlt_text1303"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1303]]},["rlt_text1304"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1304]]},["rlt_text1305"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1305]]},["rlt_text1306"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1306]]},["rlt_text14"]={["arg1"]=[[文本输出]],["arg2"]=[[你在玉雪寒团上打坐，内力源源不断地从丹田处流向全身，不过你的内力已经十分深厚，再在这玉雪寒团上修炼已无效果了。]],["id"]=[[rlt_text14]],["jobend"]=[[fb28rw03lg]]},["rlt_text15"]={["arg1"]=[[文本输出]],["arg2"]=[[你仔细研读着这石棺盖上的小字，似有所悟，原来这石棺盖之上所刻乃是一篇剑法，你不断尝试，终于将这上面所载剑法参悟！]],["id"]=[[rlt_text15]],["jobend"]=[[fb28rw02lg]]},["rlt_text16"]={["arg1"]=[[文本输出]],["arg2"]=[[你细细研读着石棺盖上所在，不过这片文字隐晦难懂，你感觉头昏脑涨，不明所以。]],["id"]=[[rlt_text16]]},["rlt_text17"]={["arg1"]=[[文本输出]],["arg2"]=[[这上面所载的天女剑法，你已经学会，无需再学了。]],["id"]=[[rlt_text17]],["jobend"]=[[fb28rw02lg]]},["rlt_text18"]={["arg1"]=[[文本输出]],["arg2"]=[[你使尽浑身力气想抬起墓门，但是墓门微丝不动。]],["id"]=[[rlt_text18]]},["rlt_text19"]={["arg1"]=[[文本输出]],["arg2"]=[[你按下了墓门旁边的机关，墓门缓缓地打开了。]],["id"]=[[rlt_text19]]},["rlt_text2"]={["arg1"]=[[文本输出]],["arg2"]=[[李漠情：小师妹，我还是劝你把玄女心经交出来吧，咱们同门一场，就不要争个你死我活了。
